// Validate webhook authentication
const headers = $input.first().json.headers;
const expectedToken = $env.N8N_WEBHOOK_AUTH_TOKEN;
const authHeader = $env.N8N_WEBHOOK_AUTH_HEADER || 'X-Lysis-Auth';

const receivedToken = headers[authHeader.toLowerCase()] || headers[authHeader];

if (!expectedToken) {
  throw new Error('N8N_WEBHOOK_AUTH_TOKEN not configured');
}

if (!receivedToken || receivedToken !== expectedToken) {
  throw new Error('Unauthorized: Invalid or missing auth token');
}

// Auth passed, forward the payload
return $input.first().json;

// Extract and validate file information from webhook payload
const payload = $input.first().json.body;

// Validate required fields
const requiredFields = ['evidence_name', 'evidence_type', 'tenant_id'];
const missing = requiredFields.filter(f => !payload[f]);

if (missing.length > 0) {
  throw new Error(`Missing required fields: ${missing.join(', ')}`);
}

// Validate tenant_id is a valid UUID
const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if (!uuidRegex.test(payload.tenant_id)) {
  throw new Error('Invalid tenant_id format');
}

return {
  tenant_id: payload.tenant_id,
  evidence_name: payload.evidence_name,
  evidence_type: payload.evidence_type,
  case_id: payload.case_id || null,
  file_path: payload.file_path,
  file_size: payload.file_size,
  mime_type: payload.mime_type,
  phash_image: payload.phash_image || null,
  source_url: payload.source_url || null,
  source_platform: payload.source_platform || null,
  collected_by: payload.collected_by || 'lysis-automation',
  collected_at: payload.collected_at || new Date().toISOString(),
  storage_bucket: payload.storage_bucket || 'forensic-evidence',
  metadata: payload.metadata || {}
};

// Calculate cryptographic hashes for integrity verification
const crypto = require('crypto');
const evidence = $input.first().json;

// Create a deterministic content identifier
// In production, this would hash the actual file content
const contentIdentifier = JSON.stringify({
  name: evidence.evidence_name,
  type: evidence.evidence_type,
  path: evidence.file_path,
  timestamp: evidence.collected_at
});

// Calculate hashes
const md5 = crypto.createHash('md5').update(contentIdentifier).digest('hex');
const sha1 = crypto.createHash('sha1').update(contentIdentifier).digest('hex');
const sha256 = crypto.createHash('sha256').update(contentIdentifier).digest('hex');
const sha512 = crypto.createHash('sha512').update(contentIdentifier).digest('hex');

return {
  ...evidence,
  hash_md5: md5,
  hash_sha1: sha1,
  hash_sha256: sha256,
  hash_sha512: sha512,
  verification_status: 'verified',
  verified_at: new Date().toISOString(),
  verified_by: 'lysis-automation'
};

// Create chain of custody log entry
const evidence = $input.first().json;

const custodyEntry = {
  timestamp: new Date().toISOString(),
  action: 'evidence_verified',
  performed_by: evidence.verified_by,
  ip_address: $input.first().json.headers?.['x-forwarded-for'] || 'internal',
  details: {
    hashes_calculated: ['md5', 'sha1', 'sha256', 'sha512'],
    verification_status: evidence.verification_status,
    phash_present: !!evidence.phash_image
  }
};

return {
  ...evidence,
  custody_log: [custodyEntry]
};

// Generate success report
const evidence = $input.first().json;

return {
  success: true,
  report_type: 'forensic_verification',
  evidence_id: evidence.id,
  tenant_id: evidence.tenant_id,
  evidence_name: evidence.evidence_name,
  verification_status: 'verified',
  hashes: {
    md5: evidence.hash_md5,
    sha1: evidence.hash_sha1,
    sha256: evidence.hash_sha256,
    sha512: evidence.hash_sha512
  },
  verified_at: evidence.verified_at,
  message: `Evidence '${evidence.evidence_name}' has been successfully verified and stored.`
};

// Handle database errors
const error = $input.first().json;

console.error('Database error:', JSON.stringify(error));

return {
  success: false,
  error: 'database_error',
  message: 'Failed to store evidence in database',
  details: error.message || 'Unknown error',
  timestamp: new Date().toISOString()
};

// Global error handler for validation/auth errors
const error = $input.first().error;
const message = error?.message || 'Unknown error occurred';

// Determine error type and appropriate status code
let statusCode = 500;
let errorType = 'internal_error';

if (message.includes('Unauthorized')) {
  statusCode = 401;
  errorType = 'authentication_error';
} else if (message.includes('Missing required') || message.includes('Invalid')) {
  statusCode = 400;
  errorType = 'validation_error';
}

return {
  success: false,
  error: errorType,
  message: message,
  timestamp: new Date().toISOString(),
  statusCode: statusCode
};
